/* ------------------------------------------------------------------ */
/* Builders                                                             */
/* ------------------------------------------------------------------ */

const CDG = "SRC-AB-COMMERCIAL-GUIDE";
const block = (code: string, kind: AcademyContentBlockSeed["kind"], title: string, ...body: string[]): AcademyContentBlockSeed => ({ code, kind, title, body });
const mod = (code: string, title: string, domain: string, minutes: number, sourceRef: string, sourceSection: string, blocks: AcademyContentBlockSeed[], extra: Partial<AcademyModuleSeed> = {}): AcademyModuleSeed =>
  ({ code, title, domain, minutes, blocks, sourceRef, sourceSection, ...extra });

type Q = [domain: string, section: string, prompt: string, correct: string, wrong: [string, string, string], explanation: string, critical?: boolean];
function bank(prefix: string, sourceRef: string, qs: Q[]): AcademyQuestion[] {
  return qs.map(([domain, section, prompt, correct, wrong, explanation, critical], i) => ({
    code: `${prefix}-P${String(i + 1).padStart(2, "0")}`, domain, prompt, options: [correct, ...wrong], correctIndex: 0, explanation, critical: !!critical, sourceRef, sourceSection: section,
  }));
}

const BOUNDARY = "Preparation only. LeaseOS study and practice do not issue a provincial driver's licence, a road-test result or a Q endorsement. The official publication governs; these questions are original LeaseOS practice questions, not government test questions.";
const studyCentre = (jurisdiction: string, notice = BOUNDARY) => ({ track: "commercial_driver" as const, jurisdiction, boundaryNotice: notice });
const boundaryBlock = (code: string) => block(code, "callout", "What this study can and cannot do", BOUNDARY);

