/* ------------------------------------------------------------------ */
/* Offline copies                                                       */
/* ------------------------------------------------------------------ */

/**
 * May LeaseOS keep an offline copy of this publication? Only when a reviewer
 * has reviewed the source AND confirmed the redistribution basis. A licence
 * the publisher states is necessary, not sufficient — somebody at the company
 * has to have read it. Otherwise the learner opens the official URL.
 */
export function offlineCopyDecision(src: { reviewStatus: string; licenceStatus: string | null; redistributionConfirmedByUserId: number | null }) {
  const blockers: string[] = [];
  if (src.reviewStatus !== "reviewed") blockers.push("Source has not been reviewed");
  if (src.licenceStatus !== "open_licence_stated") blockers.push("No stated licence permitting redistribution");
  if (!src.redistributionConfirmedByUserId) blockers.push("A reviewer has not confirmed the redistribution rights");
  return { permitted: blockers.length === 0, blockers, fallback: blockers.length ? "open_official_source" as const : null };
}
